mapper.select:
SELECT /* getActiveCodeCnt */
       COUNT(1)
  FROM TB_CODEXD
 WHERE COMM_CODE = #{commCode}
   AND COMD_CODE = #{comdCode}
   AND USEE_YSNO = 'Y'

SELECT /* dupComplaint */
       COUNT(1)
  FROM TH_CMPLNT
 WHERE USER_NUMB = #{userNumb}
   AND TAGT_TYPE = #{tagtType}
   AND TAGT_NUMB = #{tagtNumb}

mapper.insert:
INSERT /* setComplaint */
  INTO TH_CMPLNT (
       USER_NUMB
     , TAGT_TYPE
     , TAGT_NUMB
     , TAGT_USER
     , TAGT_CNTN
     , CMPL_RSON
     , CMPL_CNTN
     , CMPL_STAT
) VALUES (
       #{userNumb}
     , #{complaint.tagtType}
     , #{complaint.tagtNumb}
     , #{complaint.tagtUser}
     , #{complaint.tagtCntn,jdbcType=LONGVARCHAR}
     , #{complaint.cmplRson}
     , #{complaint.cmplCntn,jdbcType=VARCHAR}
     , 'CMPL_RECEIVED'
)
